import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] inputLine = br.readLine().split(" ");
        int x = Integer.parseInt(inputLine[0]);
        int y = Integer.parseInt(inputLine[1]);

        List<Integer> primesList = generatePrimes(6000);
        Map<Integer, Integer> fValues = new HashMap<>();
        fValues.put(0, 0);
        fValues.put(1, 1);
        fValues.put(2, 2);

        for (int i = 3; i <= x; i++) {
            int val = 2 * fValues.get(i - 1);
            List<Integer> allFactors = allFactors(i, primesList);
            for (int divisor : allFactors) {
                if (divisor >= 2 && divisor <= i) {
                    int quotient = i / divisor;
                    int prevDivisor = (i - 1) / divisor;
                    int delta = fValues.getOrDefault(quotient, 0) - fValues.getOrDefault(prevDivisor, 0);
                    val += delta;
                }
            }
            val %= y;
            fValues.put(i, val);
        }
        System.out.println(fValues.get(x));
    }

    private static List<Integer> generatePrimes(int limit) {
        List<Integer> primes = new ArrayList<>();
        for (int candidate = 2; candidate < limit; candidate++) {
            boolean isPrime = true;
            for (int prime : primes) {
                if (prime * prime > candidate) {
                    break;
                }
                if (candidate % prime == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                primes.add(candidate);
            }
        }
        return primes;
    }

    private static Map<Integer, Integer> getPrimeFactors(int number, List<Integer> primesList) {
        Map<Integer, Integer> factorsMap = new HashMap<>();
        int tempNumber = number;
        for (int prime : primesList) {
            if (prime * prime > tempNumber) {
                break;
            }
            int count = 0;
            while (tempNumber % prime == 0) {
                tempNumber /= prime;
                count++;
            }
            if (count > 0) {
                factorsMap.put(prime, count);
            }
        }
        if (tempNumber > 1) {
            factorsMap.put(tempNumber, 1);
        }
        return factorsMap;
    }

    private static List<Integer> allFactors(int number, List<Integer> primesList) {
        Map<Integer, Integer> primeFactors = getPrimeFactors(number, primesList);
        List<Integer> resultFactors = new ArrayList<>();
        resultFactors.add(1);
        for (Map.Entry<Integer, Integer> entry : primeFactors.entrySet()) {
            int prime = entry.getKey();
            int exponent = entry.getValue();
            List<Integer> newFactors = new ArrayList<>();
            for (int val : resultFactors) {
                for (int exp = 0; exp <= exponent; exp++) {
                    newFactors.add(val * (int) Math.pow(prime, exp));
                }
            }
            resultFactors = newFactors;
        }
        return resultFactors;
    }
}
